import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and single base premiums ---
  it.todo("quotes an empty item list as 5 G (processing fee only)");
  it.todo("quotes a single plain sword as 105 G (100 G base + 5 G fee)");
  it.todo("quotes a single plain amulet as 65 G (60 G base + 5 G fee)");
  it.todo("quotes a single plain staff as 85 G (80 G base + 5 G fee)");
  it.todo("quotes a single plain potion as 45 G (40 G base + 5 G fee)");
  it.todo("quotes a single rune as 30 G (25 G base + 5 G fee)");
  it.todo("quotes a single moonstone as 30 G (25 G base + 5 G fee)");
  it.todo("quotes a sword and an amulet as 165 G (100 + 60 base + 5 G fee)");

  // --- Component blocks of 3 alike ---
  it.todo("quotes 2 runes with a 50 G base premium (no block)");
  it.todo("quotes 3 runes with a 60 G base premium (block applies)");
  it.todo("quotes 4 runes with a 100 G base premium (block requires exactly 3)");
  it.todo("quotes 7 runes with a 175 G base premium (no block for 7)");
  it.todo("quotes 2 runes + 1 moonstone with a 75 G base premium (alike means same type, so no block)");
  it.todo("quotes 3 runes + 3 moonstones with a 120 G base premium (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to a cursed sword: base 100 G + 50 G");
  it.todo("adds a 30 % high-enchantment surcharge to a sword with enchantment 5 (threshold)");
  it.todo("adds no high-enchantment surcharge to a sword with enchantment 4");
  it.todo("adds both curse and high-enchantment surcharges to a cursed sword with enchantment 5");
  it.todo("applies the curse surcharge only to the cursed item: cursed sword + plain amulet → 210 G before fee (160 base + 50 curse)");

  // --- Policy-wide modifiers ---
  it.todo("applies a 20 % loyalty discount at exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies a 10 % first-insurance surcharge on the policy base premium");
  it.todo("applies a 15 % follow-up discount to the customer's second quote");
  it.todo("applies the first-insurance surcharge to every quote, including follow-up contracts");

  // --- Rounding ---
  it.todo("rounds a premium of 197.5 G up to 198 G (in the MHPCO's favor)");
  it.todo("rounds a payout of 350.5 G down to 350 G (in the MHPCO's favor)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years) as 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) as 160 G");

  // --- Claims: standard reimbursement and deductible ---
  it.todo("pays out 400 G for a steel sword (enchantment 3) with 500 G damage (500 − 100 deductible)");
  it.todo("pays out 100 G for a rune with 200 G damage (runes have no enchantment or material)");
  it.todo("applies the 100 G deductible per damaged item: sword 500 G + amulet 300 G → 600 G");

  // --- Claims: special clauses ---
  it.todo("reimburses 50 % for a steel sword with enchantment 9 and 1000 G damage → 400 G");
  it.todo("reimburses 50 % at exactly enchantment 8: dragon sword, 1000 G damage → 400 G");
  it.todo("fully reimburses a dragon-material sword with enchantment 5 and 800 G damage → 700 G");
  it.todo("lets the 50 % rule win over dragon material: dragon sword, enchantment 9, 1000 G damage → 400 G");

  // --- Claims: cap ---
  it.todo("caps a policy at twice the insurance sum: sword + amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("bases the cap on unmodified insurance values: cursed sword → cap 2000 G despite a 165 G premium");
  it.todo("bases the insurance sum on full component values: sword + 3 runes → insurance sum 1750 G despite the block discount");
  it.todo("reports remainingCap 600 G after a first 1500 G claim against a sword policy (payout 1400 G)");
  it.todo("reduces a second 1500 G claim to the remaining cap: payout 600 G, remainingCap 0 G");

  // --- Multiple items of the same type ---
  it.todo("insures two swords with an insurance sum of 2000 G and a cap of 4000 G");
  it.todo("treats two sword damage entries as separate damages, each with its own deductible");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (Error thrown; CLI exits non-zero)");

  // --- Error cases (chosen contract: the domain throws Error; the CLI exits non-zero and writes to stderr) ---
  it.todo("rejects a quote containing an unknown item type such as broomstick (Error thrown)");
  it.todo("rejects a claim for an item that is not part of the policy, e.g. an amulet when only a sword is insured (Error thrown)");
  it.todo("rejects a claim damage entry with an unknown item type (Error thrown)");
  it.todo("rejects a claim damage entry with a negative amount such as -200 (Error thrown)");

  // --- CLI adapter ---
  it.todo("CLI reads a scenario from stdin and writes {results:[...]} to stdout in step order");
  it.todo("CLI writes a quote result as {premium} and a claim result as {payout, remainingCap}");
  it.todo("CLI exits non-zero, writes an error to stderr, and writes no results to stdout for an unknown item type");
});
EOF
