cat > src/claim-office.ts <<'EOF'
export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_DIVISOR = 10;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
};

// eslint-disable-next-line @typescript-eslint/no-unused-vars -- the customer matters once loyalty applies
export function quote(customer: Customer, items: Item[]): number {
  const policyBasePremium = items.reduce(
    (total, item) => total + BASE_PREMIUM_BY_TYPE[item.type],
    0,
  );
