cat > src/cli.ts <<'EOF'
import { readFileSync } from "node:fs";
import {
  ClaimOffice,
  type ClaimResult,
  type Customer,
  type Incident,
  type Item,
} from "./claim-office.js";

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

type Step = QuoteStep | ClaimStep;

interface Scenario {
  customer: Customer;
  steps: Step[];
}

type StepResult = { premium: number } | ClaimResult;

function runStep(office: ClaimOffice, step: Step): StepResult {
  if (step.op === "quote") {
    return { premium: office.quote(step.items) };
  }
  return office.claim(step.policy, step.incident);
}

function runScenario(scenario: Scenario): StepResult[] {
  const office = new ClaimOffice(scenario.customer);
  return scenario.steps.map((step) => runStep(office, step));
}

function main(): void {
  const scenario = JSON.parse(readFileSync(0, "utf8")) as Scenario;
  const results = runScenario(scenario);
  process.stdout.write(JSON.stringify({ results }));
}

try {
  main();
} catch (error) {
  process.stderr.write(`${(error as Error).message}\n`);
  process.exit(1);
}
EOF
